"""Private teacher support. No import-time native work; no checkpoint writes."""
import pathlib,hashlib,os,time,json,sys,re,gzip,csv,shutil,copy

LIGHTNING_SHA='f1d8857032d66c6df4022c0abf58b5456b164c42055e2d791b749e2bb5423036'
def digest_file(path):
    h=hashlib.sha256()
    with pathlib.Path(path).open('rb') as f:
        for block in iter(lambda:f.read(1048576),b''):h.update(block)
    return h.hexdigest()

def allocated(root):
    total=apparent=files=0
    for p in pathlib.Path(root).rglob('*'):
        try:
            if p.is_file():
                s=p.stat();total+=s.st_blocks*512;apparent+=s.st_size;files+=1
        except FileNotFoundError:pass
    return {'allocated_bytes':total,'apparent_bytes':apparent,'files':files}

def identity(pid):
    p=pathlib.Path('/proc')/str(pid);parts=(p/'stat').read_text().rsplit(')',1)[1].split()
    return {'pid':pid,'uid':p.stat().st_uid,'startticks':parts[19],'cwd':os.readlink(p/'cwd'),'cmdline':(p/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')}

def tool_snapshot(binary):
    p=pathlib.Path(binary);digest=digest_file(p)
    if digest!=LIGHTNING_SHA:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR Lightning tool SHA differs')
    s=p.stat();result={'lightning':{'path':str(p),'sha256':digest,'inode':s.st_ino,'bytes':s.st_size}}
    pins={'tidb-server':'dec86f02f3e92ce28f923c669084a668f5899d2e58128b903e8d07550e067140','pd-server':'1d53fa7a4bbfb317b70f4377208e6e3b1d75f840568747120a21e1a04390dd9f','tikv-server':'164d0ee03d2f98bbad562f2df5b6810644bc9d57f60671258fdc854c1750043f'}
    for name,pin in pins.items():
        found=shutil.which(name)
        if found is None:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR missing pinned core '+name)
        path=pathlib.Path(found);value=digest_file(path)
        if value!=pin:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR core SHA differs '+name)
        result[name]={'path':str(path),'sha256':value,'bytes':path.stat().st_size}
    return result

def _write(path,value):path.write_text(json.dumps(value,ensure_ascii=False,default=str,indent=2)+'\n',encoding='utf8')

def _current(data,config):
    return {'files':{p.relative_to(data).as_posix():digest_file(p)for p in data.rglob('*')if p.is_file()},'config_sha256':digest_file(config)}

def read_checkpoint(path):
    """Use the supplied official protobuf runtime and official descriptor only.
    Dependency locations/pins are recorded in dependencies.json. Missing tools
    are environmental preparation failures, never student semantic rejection.
    """
    deps=json.loads((pathlib.Path(__file__).parent/'dependencies.json').read_text(encoding='utf8'))
