def finish_case(cluster,conn,callback,binary,root,export,data,config,checkpoint,sorted_dir,approved,count,factor,offset,modulus,original_identity,grants,result,deadline,query):
    """Always run all independent postchecks; never erase a failed primary path."""
    phase=result['phase'];result['post_checks']={};callback_error=None
    expected=tuple((i,(i*factor+offset)%modulus)for i in range(1,count+1))
    def check(name,fn):
