        before_signal=initial.split('got signal to exit',1)[0]
        if phase=='encoding':assert 'encode kv data and write start'in before_signal and 'encode kv data and write completed'not in before_signal
        elif phase=='import':assert 'start import engine'in before_signal and 'import engine success'not in before_signal
        else:assert 'remote checksum start'in before_signal and 'remote checksum completed'not in initial and 'checksum pass'not in initial
        assert _current(data,config)==approved and digest_file(checkpoint)==result['after_SIGTERM_checkpoint_sha256']
        result['source_CP_sorted_preserved_before_callback']=True
        if time.monotonic()>=deadline-8:raise TimeoutError('Shared grading deadline reserve reached before callback')
        logs=root/'callback-logs';logs.mkdir()
        # Same original six-argument student interface, no private implementation
        # requirements or rewritten callback return values.
        callback_started=time.monotonic()
        try:result['callback_return']=callback(conn,str(binary),str(config),str(data),copy.deepcopy(approved),str(logs))
        except BaseException as exc:
