            result['outcome']='same_CP_success'
        else:
            # The already observed native cancellation outcome is not assumed.
            # If a new engine run resumes successfully and proves all values,
            # that is also a valid real outcome; no fabricated STOP is required.
            if callback_error is None:
                assert current_rows==expected and after_cp['table_status']==200,'Fake success over incomplete physical import'
