            else:
                preexisting_inconsistent=stopped_cp['engines'].get('0',{}).get('status')==120 and result['target_rows_after_SIGTERM']!=count
                # Exact official Checksum180/SetInvalid(/10)=18 under the
                # immutable required-checksum config is native error context.
                # Combine it with unchanged task identity and full row mismatch,
                # not any private error wording/log filename or exit code alone.
