        result['live_case_material_retained_for_outer_cleanup']=str(root)
        _write(export/'result.json',result)
    return result

def run_three_phases(cluster,resume_callback,root,binary,query,allocate_ports,deadline,seed):
    """Teacher-only procedural entry; caller owns cluster and final cleanup.
    deadline is the original grade's absolute monotonic deadline, never a fresh
    per-case120s allowance. No drop/reset happens inside any resume boundary.
    """
    assert os.getuid()==1000 and callable(resume_callback)
    root=pathlib.Path(root);root.mkdir(parents=True,exist_ok=False)
    assert root.resolve().is_relative_to(pathlib.Path(cluster.root).resolve())
    results=[]
    for phase in ['encoding','import','checksum']:
        if time.monotonic()>deadline-12:raise TimeoutError('Shared120s budget insufficient; not verified')
        if results:
            assert results[-1]['case_evidence_closed']
            if not results[-1]['passed']:break
            # The previous independent case is now fully recorded. This is not
            # a resume/recovery operation; original CP/sorted/source stay intact.
            c=cluster.connect('training')
            try:query(c,'DROP TABLE import_rows')
            finally:c.close()
        module=__import__('phase_'+phase)
        digest=hashlib.sha256((str(seed)+':'+phase).encode()).digest()
        factor=10001+int.from_bytes(digest[:4],'big')%900000
        offset=int.from_bytes(digest[4:12],'big')%1000000000
        result=module.run_case(cluster,resume_callback,root/phase,binary,deadline,query,allocate_ports,(factor,offset));results.append(result)
    compact=[{**{k:r.get(k)for k in ['phase','passed','outcome','native_phase_interruptions','stopped_CP','after_callback_CP','actual_rows','full_values_equal','callback_seconds','primary_error','disk_budget_observed','target_ddl_saved','target_ddl_unchanged_from_stopped']},'post_checks':{name:bool(value['executed']and value['passed'])for name,value in r['post_checks'].items()},**({'observation_error':r.get('observation_error'),'post_check_errors':{name:value.get('error')for name,value in r['post_checks'].items()if not value['passed']},'failure_native_tail':r.get('failure_native_tail')}if r.get('primary_error')or r.get('observation_error')else{})}for r in results]
    _write(root/'combined-result.json',{'passed':len(results)==3 and all(r['passed']for r in results),'cases':compact,'outer_cluster_cleanup_required':True,'accepted_increment':0})
    return compact

